/*
 * La posición se obtiene de Motoboy en el momento de la consulta, pero el día
 * selecciona qué reservas aportan repartidores. Antes de las 15:00 se usa la
 * última jornada operativa para seguir actualizando pendientes: normalmente
 * ayer, pero los lunes se salta el domingo y se toma el sábado. Desde las
 * 15:00 se usan las rutas de hoy.
 */

const cuerpo = $json?.body ?? $json ?? {};
const pedido = typeof cuerpo.dia === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(cuerpo.dia)
  ? cuerpo.dia
  : null;
const ahora = new Date();
const hoy = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Mexico_City',
  year: 'numeric', month: '2-digit', day: '2-digit',
}).format(ahora);
const hora = Number(new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Mexico_City', hour: '2-digit', hourCycle: 'h23',
}).formatToParts(ahora).find((p) => p.type === 'hour')?.value);
const [anio, mes, fecha] = hoy.split('-').map(Number);
const fechaLocal = new Date(Date.UTC(anio, mes - 1, fecha));
const diaSemana = fechaLocal.getUTCDay();
fechaLocal.setUTCDate(fechaLocal.getUTCDate() - (diaSemana === 1 ? 2 : 1));
const anterior = fechaLocal.toISOString().slice(0, 10);
const dia = pedido ?? (hora < 15 ? anterior : hoy);

return [{ json: { dia, origen: pedido ? 'tablero' : 'horario' } }];

/*
 * Repartidores a columnas de Postgres.
 *
 * `primera_deteccion`, `ultima_deteccion` y `sincronizado_en` no se mapean: las
 * escribe un trigger de la base. Es lo que hace que `primera_deteccion`
 * sobreviva al upsert en vez de quedar pisada en cada corrida y terminar
 * siempre igual a la última.
 */
/*
 * sync_id y día vienen pegados a cada fila que devolvió SQL Server, así que
 * en el camino normal no se cruza el grafo. El `$('...')` es solo el
 * respaldo para la corrida sin filas -ahí no hay fila de donde sacarlos- y
 * va dentro de un try/catch: si la cadena de items se cortó, n8n tira
 * «el nodo no se ejecutó», y eso no puede matar al flujo entero.
 */
const primera = $input.all()[0]?.json ?? {};
let sync = primera.SyncId ?? null;
let dia = primera.Dia ? String(primera.Dia).slice(0, 10) : null;

if (!sync || !dia) {
  try {
    sync = sync ?? $('Abrir sincronización').first().json.sync_id;
    dia = dia ?? String($('Abrir sincronización').first().json.dia).slice(0, 10);
  } catch {
    // Sin respaldo tampoco: se sigue con lo que haya. El cierre no va a
    // encontrar filas con este sync_id y no va a desactivar nada, que es
    // el comportamiento correcto cuando no se pudo leer nada.
  }
}

const texto = (v) => {
  const t = String(v ?? '').trim();
  return t === '' || t.toLowerCase() === 'null' ? null : t;
};
const entero = (v) =>
  v === null || v === undefined || v === '' || !Number.isFinite(Number(v))
    ? null
    : Math.trunc(Number(v));
const marca = (v) => {
  if (!v) return null;
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
};

/*
 * La misma regla que `coordenadaValida` en web/src/lib/tracker.ts.
 *
 * El (0, 0) se descarta aparte del rango: es un par válido como número y no lo
 * es como posición. Es lo que reporta un equipo que todavía no consiguió
 * señal, y cae en el Atlántico. Sin este corte, todos los repartidores sin GPS
 * aparecerían amontonados frente a la costa de África.
 */
const coordenada = (lat, lon) => {
  const a = Number(lat);
  const b = Number(lon);
  if (!Number.isFinite(a) || !Number.isFinite(b)) return null;
  if (a < -90 || a > 90 || b < -180 || b > 180) return null;
  if (a === 0 && b === 0) return null;
  return { lat: a, lon: b };
};

const filas = $input
  .all()
  .map((i) => i.json)
  .filter((r) => Number.isFinite(Number(r.IdMotoboy)) && Number(r.IdMotoboy) > 0);

let omitidos = 0;

const salida = filas.map((r) => {
  const punto = coordenada(r.Latitud, r.Longitud);
  if (!punto) omitidos += 1;

  return {
    json: {
      hay: true,
      id_motoboy: Number(r.IdMotoboy),
      nombre: texto(r.Nombre),
      apellido: texto(r.Apellido),

      /*
       * Un repartidor sin coordenadas válidas se guarda igual, sin posición.
       * Está operando y tiene que aparecer en el panel: «salió y no está
       * transmitiendo» es un dato que la operación mira. Lo que no se hace es
       * dibujarlo en un lugar que no es.
       */
      latitud: punto?.lat ?? null,
      longitud: punto?.lon ?? null,
      fecha_ultima_posicion: punto ? marca(r.UltimaActualizacion) : null,

      ultima_info: texto(r.UltimaInfo),
      id_reserva: entero(r.IdReserva),
      id_localidad: entero(r.IdLocalidad),
      id_modalidad: entero(r.IdModalidad),
      reserva_desde: marca(r.FechaDesde),
      reserva_hasta: marca(r.FechaHasta),

      fecha_operacion: dia,

      // Todo lo que esta corrida ve está activo. Los que dejó de ver los apaga
      // `tracker_cerrar_drivers`, y solo si la corrida terminó bien.
      activo: true,
      sync_id: sync,
    },
  };
});

for (const item of salida) {
  item.json.leidos = filas.length;
  item.json.omitidos = omitidos;
}

/*
 * Sin repartidores, un item testigo.
 *
 * Un nodo sin items de entrada no se ejecuta, así que devolver el arreglo
 * vacío dejaría la sincronización abierta en `running` hasta que venza sola y
 * bloqueando el botón mientras tanto. El testigo mantiene la cadena viva hasta
 * el cierre, que con `leidos = 0` no desactiva nada.
 */
// El testigo lleva sync_id y fecha porque el nodo que cierra los lee de su
// entrada directa, no de otro nodo.
return salida.length > 0
  ? salida
  : [{ json: { hay: false, leidos: 0, omitidos: 0, sync_id: sync, fecha_operacion: dia } }];

/*
 * Motoboy.UltimaActualizacion llega sin zona desde SQL Server. La evidencia
 * operativa mostró un desfase uniforme de tres horas: el reloj de origen es
 * Argentina (UTC-3), mientras que la consulta lo había interpretado como UTC.
 *
 * Las coordenadas no cambian; se corrige solamente el instante asociado al
 * reporte para que la antigüedad del punto se calcule contra la hora real.
 */
const DESFASE_ARGENTINA_MS = 3 * 60 * 60 * 1000;

return $input.all().map((item) => {
  const fecha = new Date(item.json.UltimaActualizacion);
  if (Number.isNaN(fecha.getTime())) return item;

  return {
    ...item,
    json: {
      ...item.json,
      UltimaActualizacion: new Date(fecha.getTime() + DESFASE_ARGENTINA_MS).toISOString(),
    },
  };
});

/*
 * El motivo de la falla, recortado y sin comillas, más el sync_id a mano.
 *
 * Esta rama es la última línea de defensa: es la que evita que una corrida
 * muerta deje su fila en `running` reteniendo el lock. Por eso no puede
 * reventar ella misma, y por eso el sync_id se resuelve acá adentro, con
 * try/catch, en vez de en la expresión del nodo que sigue.
 *
 * La diferencia importa: si `Abrir sincronización` no llegó a ejecutarse -el
 * flujo murió antes, o alguien corrió un nodo suelto desde el editor-, una
 * expresión `$('Abrir sincronización')` tira ExpressionError y se lleva puesta
 * a la propia rama de error. Un Code node puede atajarlo; una expresión no.
 *
 * Sin sync_id se sigue igual, con la cadena vacía: la consulta la convierte en
 * NULL y `tracker_fallar_sync` no encuentra ninguna fila que marcar. No hay
 * nada que cerrar, que es exactamente el caso.
 */
let sync = '';
try {
  sync = $('Abrir sincronización').first().json.sync_id ?? '';
} catch {
  sync = '';
}

/*
 * El mensaje se limpia por dos razones. Una es que se interpola en una consulta
 * y una comilla suelta la partiría al medio. La otra es que el error de un
 * driver de base puede traer la fila que estaba procesando, y de ahí a dejar un
 * domicilio guardado en la tabla de ejecuciones hay un paso. La función de
 * Postgres vuelve a recortar a 500: son dos redes para lo mismo, a propósito.
 */
const bruto = $json?.error?.message ?? $json?.error ?? 'El flujo se cortó sin detalle.';

const motivo = String(bruto)
  .replace(/['"\\]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 200) || 'El flujo se cortó sin detalle.';

return [{ json: { sync_id: String(sync), motivo } }];
